 public EntryPointAuthorityResponse updateEntry(String id,UpdateEntryPointAuthorityRequest r,long v,IamApiRequestContext c){String key=c.requireIdempotencyKey();String reason=c.requireAuditReason();return idempotency.execute(INSTANCE,c.actorId(),"permission.entry-point.update",key,r,200,EntryPointAuthorityResponse.class,()->EntryPointAuthorityResponse.from(port.updateEntryPoint(new UpdateEntryPointAuthorityCommand(id,r.ownerModule(),EntryPointAuthorityState.valueOf(r.authorityState().toUpperCase(Locale.ROOT)),opt(r.targetPermissionCode()),opt(r.legacyAuthorityType()),r.legacyAuthorities(),r.resourceType(),r.resourceResolverId(),opt(r.exemptionReason()),Optional.ofNullable(r.migrationDeadline()),v,c.actorId(),c.correlationId(),reason,c.requestedAt()))));}
 public LegacyAuthorityMappingResponse updateMapping(String id,UpdateLegacyAuthorityMappingRequest r,long v,IamApiRequestContext c){String key=c.requireIdempotencyKey();String reason=c.requireAuditReason();return idempotency.execute(INSTANCE,c.actorId(),"permission.legacy-mapping.update",key,r,200,LegacyAuthorityMappingResponse.class,()->LegacyAuthorityMappingResponse.from(port.updateMapping(new UpdateLegacyAuthorityMappingCommand(id,opt(r.targetPermissionCode()),r.ownerModule(),r.status(),Optional.ofNullable(r.migrationDeadline()),r.notes()==null?"":r.notes(),v,c.actorId(),c.correlationId(),reason,c.requestedAt()))));}
 public EntryPointBypassResponse createBypass(CreateEntryPointBypassRequest r,IamApiRequestContext c){String key=c.requireIdempotencyKey();String reason=c.requireAuditReason();return idempotency.execute(INSTANCE,c.actorId(),"permission.entry-point-bypass.create",key,r,201,EntryPointBypassResponse.class,()->EntryPointBypassResponse.from(port.createBypass(new CreateEntryPointBypassCommand(UUID.randomUUID().toString(),r.entryPointId(),r.ownerId(),r.reason(),r.replacement(),r.expiresAt(),c.actorId(),c.correlationId(),reason,c.requestedAt()))));}
 public EntryPointBypassResponse revokeBypass(String id,RevokeEntryPointBypassRequest r,long v,IamApiRequestContext c){String key=c.requireIdempotencyKey();String reason=c.requireAuditReason();return idempotency.execute(INSTANCE,c.actorId(),"permission.entry-point-bypass.revoke",key,r,200,EntryPointBypassResponse.class,()->EntryPointBypassResponse.from(port.revokeBypass(new RevokeEntryPointBypassCommand(id,v,r.reason(),c.actorId(),c.correlationId(),reason,c.requestedAt()))));}
 public List<ApplicationPermissionManifestResponse> manifests(int limit){return port.manifests(limit).stream().map(ApplicationPermissionManifestResponse::from).toList();}
 public ApplicationPermissionManifestResponse manifest(String id){return ApplicationPermissionManifestResponse.from(port.manifest(id));}
 public List<ApplicationPermissionManifestEntryResponse> manifestEntries(String id,String driftStatus,int limit){return port.manifestEntries(id,driftStatus,limit).stream().map(ApplicationPermissionManifestEntryResponse::from).toList();}
