 public List<PermissionCoverageEvidenceResponse> coverageEvidence(int limit){return port.coverageEvidence(limit).stream().map(PermissionCoverageEvidenceResponse::from).toList();}
 public ApplicationPermissionManifestResponse registerManifest(RegisterApplicationPermissionManifestRequest r,IamApiRequestContext c){
  String key=c.requireIdempotencyKey();String reason=c.requireAuditReason();
  return idempotency.execute(INSTANCE,c.actorId(),"permission.manifest.register",key,r,201,ApplicationPermissionManifestResponse.class,()->{
   var stats=r.statistics();var binding=r.catalogBinding();
   List<PermissionManifestRegistrationEntry> entries=r.entries().stream().map(e->new PermissionManifestRegistrationEntry(
     e.entryPointId(),e.entryPointType(),e.ownerModule(),e.displayName(),opt(e.routePattern()),opt(e.httpMethod()),e.authorityState(),
     e.protectionMode(),e.coverageStatus(),opt(e.permissionCode()),e.legacyAuthorities(),e.resourceType(),e.resourceResolverId(),
     e.scopeRequired(),opt(e.exemptionReason()),e.sourceRef(),e.sourceHash(),e.descriptorHash())).toList();
   return ApplicationPermissionManifestResponse.from(port.registerManifest(new RegisterApplicationPermissionManifestCommand(
     UUID.randomUUID().toString(),r.applicationId(),r.environment(),r.buildVersion(),r.manifestRevision(),r.schemaVersion(),
     r.contentHash(),binding.revisionId(),binding.revisionCode(),r.sourceInventoryRevision(),stats.entryCount(),
     stats.protectedEntryCount(),stats.coveredEntryCount(),stats.coveragePercent(),stats.targetPermissionCount(),
     stats.legacyAuthorityCount(),stats.exemptCount(),stats.delegatedCount(),stats.uncoveredCount(),entries,
     c.actorId(),c.correlationId(),reason,c.requestedAt())));
  });
 }
