 private Optional<String> opt(String v){return v==null||v.isBlank()?Optional.empty():Optional.of(v.trim());} public ShadowPipelineReadinessResponse shadowPipelineReadiness(){return ShadowPipelineReadinessResponse.from(port.shadowPipelineReadiness());}
